def persist(store, value):
    import sqlite3
    return sqlite3.connect(value)

def persist(store, value):
    query = 'INSERT INTO work_items (body) VALUES (?)'
    return store.execute(query, [value])

def open(port, value):
    packet = {'jsonrpc': '2.0', 'id': 1, 'method': 'save', 'params': {'body': value}}
    return port.execute(packet)
